package scratch

import org.junit.jupiter.api.Test
import tools.jackson.databind.DeserializationFeature
import tools.jackson.databind.MapperFeature
import tools.jackson.databind.json.JsonMapper
import tools.jackson.module.kotlin.KotlinModule

/** Throwaway probe of Jackson 3 defaults; deleted after use. */
class ScratchJacksonTest {
    /** Probe DTO. */
    data class Q(val quantity: Int)

    /** Prints what each body turns into. */
    @Test
    fun probe() {
        val bodies = listOf("null", "[5]", "{}", """{"quantity": null}""", """{"quantity": "5"}""", """{"quantity": 1.5}""", """{"quantity": 3000000000}""", """{"quantity": 5} x""")
        val default = JsonMapper.builder().addModule(KotlinModule.Builder().build()).build()
        val strict = JsonMapper.builder().addModule(KotlinModule.Builder().build())
            .disable(DeserializationFeature.ACCEPT_FLOAT_AS_INT)
            .disable(MapperFeature.ALLOW_COERCION_OF_SCALARS).build()
        println("FAIL_ON_NULL_FOR_PRIMITIVES default=" + default.isEnabled(DeserializationFeature.FAIL_ON_NULL_FOR_PRIMITIVES))
        println("ACCEPT_FLOAT_AS_INT default=" + default.isEnabled(DeserializationFeature.ACCEPT_FLOAT_AS_INT))
        println("ALLOW_COERCION_OF_SCALARS default=" + default.isEnabled(MapperFeature.ALLOW_COERCION_OF_SCALARS))
        for ((name, m) in listOf("default" to default, "strict" to strict)) for (b in bodies) {
            val r = runCatching { m.readValue(b, Q::class.java) }
            println("PROBE $name [$b] -> " + r.fold({ "OK $it" }, { "FAIL ${it::class.simpleName}: ${it.message?.lineSequence()?.first()}" }))
        }
    }
}
